// ===== ตั้งค่า: แก้ 3 ค่านี้ครั้งเดียว =====
return [{
  json: {
    // อีเมลที่จะรับแจ้งเตือนเมื่อได้ไฟล์ใหม่ / ครบ 11 ไฟล์ — หลายคนคั่นด้วยจุลภาค เช่น 'a@company.com, b@company.com'
    notifyEmail: 'ใส่อีเมลของคุณ@example.com',
    // ID โฟลเดอร์ Google Drive ที่จะเก็บ Playlist (ดูจากลิงก์โฟลเดอร์: drive.google.com/drive/folders/<ID>)
    parentFolderId: 'ใส่_ID_โฟลเดอร์_Google_Drive',
    // ใส่อีเมลผู้ส่ง Playlist ถ้ามี (คั่นด้วย OR) เช่น 'a@company.com OR b@company.com' — เว้นว่าง = ดูทุกอีเมลที่มีไฟล์ Excel แนบ
    fromFilter: '',
    // Playlist 11 แบบที่ระบบเติมใบเช็ครูปต้องใช้ (ชื่อ + รูปแบบชื่อไฟล์)
    kinds: [
      { name: 'แยกจอ 40Blue', pattern: '40\\s*Blue' },
      { name: 'แยกจอ 40Red', pattern: '40\\s*Red' },
      { name: 'แยกจอ 80Blue', pattern: '80\\s*Blue' },
      { name: 'แยกจอ 80Red', pattern: '80\\s*Red' },
      { name: 'แยกจอ CITY', pattern: 'แยกจอ.*CITY|[_\\s]CITY[_\\s.]' },
      { name: 'แยกจอ Spare', pattern: 'Spare' },
      { name: 'Signature Max', pattern: 'Signature' },
      { name: 'Show DC', pattern: 'Show\\s*DC' },
      { name: 'BKJ1', pattern: 'BKJ\\s*1' },
      { name: 'BKJ2', pattern: 'BKJ\\s*2' },
      { name: 'Metro LED', pattern: 'Metro' },
    ],
  },
}];

// คัดไฟล์ Playlist ของ "วันนี้" จากอีเมล 2 วันล่าสุด (เผื่อ Playlist ส่งมาตั้งแต่เย็นวันก่อน)
// วันที่ของไฟล์ดูจากชื่อไฟล์ก่อน เช่น 2026_10_09, 2026_Oct_09, 9-10-26, 9 Oct 2026 — ถ้าชื่อไม่มีวันที่ ใช้วันที่ของอีเมล
// เก็บทุกไฟล์ที่เข้า 11 แบบ (บางวันมีมากกว่า 1 ไฟล์ต่อแบบ เช่น Signature Max ฉบับระหว่างวัน) และไม่อัปโหลดไฟล์เดิมซ้ำ
const cfg = $('ตั้งค่า').first().json;
const kinds = cfg.kinds.map(k => ({ name: k.name, re: new RegExp(k.pattern, 'i') }));
const sd = $getWorkflowStaticData('global');
const today = $now.setZone('Asia/Bangkok').toFormat('yyyy-MM-dd');
if (sd.day !== today) { sd.day = today; sd.sent = {}; sd.folderId = ''; }

// ---- อ่านวันที่จากชื่อไฟล์ (กติกาเดียวกับ playlist_system.html) ----
const MON = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11 };
const THM = { 'มค': 0, 'กพ': 1, 'มีค': 2, 'เมย': 3, 'พค': 4, 'มิย': 5, 'กค': 6, 'สค': 7, 'กย': 8, 'ตค': 9, 'พย': 10, 'ธค': 11 };
const thisYear = +today.slice(0, 4);
const yy = y => { y = +y; if (y < 100) y += y >= 60 ? 2500 : 2000; if (y > 2400) y -= 543; return y; };
const ymd = (y, m, d) => (m >= 0 && m < 12 && d >= 1 && d <= 31)
  ? `${y}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}` : null;
function nameDate(n) {
  n = String(n).replace(/\.xls[xm]?$/i, '');
  let m = n.match(/(?:^|[^\d])(\d{4})[-_. ](\d{1,2})[-_. ](\d{1,2})(?!\d)/);
  if (m) return ymd(yy(m[1]), +m[2] - 1, +m[3]);
  m = n.match(/(?:^|[^\d])(\d{4})[-_. ]?(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*[-_. ]?(\d{1,2})(?!\d)/i);
  if (m) return ymd(yy(m[1]), MON[m[2].toLowerCase()], +m[3]);
  m = n.match(/(?:^|[^\d])(\d{1,2})[-_.](\d{1,2})[-_.](\d{2,4})(?!\d)/);
  if (m) return ymd(yy(m[3]), +m[2] - 1, +m[1]);
  m = n.replace(/\s+/g, '').match(/(\d{1,2})(ม\.?ค\.?|ก\.?พ\.?|มี\.?ค\.?|เม\.?ย\.?|พ\.?ค\.?|มิ\.?ย\.?|ก\.?ค\.?|ส\.?ค\.?|ก\.?ย\.?|ต\.?ค\.?|พ\.?ย\.?|ธ\.?ค\.?)(\d{2,4})?/);
  if (m) return ymd(m[3] ? yy(m[3]) : thisYear, THM[m[2].replace(/\./g, '')], +m[1]);
  m = n.match(/(?:^|[^A-Za-z\d])(\d{1,2})[-_ ]?(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*[-_ ]?(\d{2,4})?(?![A-Za-z])/i);
  if (m) return ymd(m[3] ? yy(m[3]) : thisYear, MON[m[2].toLowerCase()], +m[1]);
  return null;
}
const bkkDay = d => { const t = new Date(d).getTime(); return t ? new Date(t + 7 * 3600e3).toISOString().slice(0, 10) : null; };

const files = {};
const others = new Set(); // ไฟล์ Excel ของวันนี้ที่ชื่อไม่ตรง 11 แบบ
for (const item of $input.all()) {
  const mailDay = bkkDay(item.json.date);
  for (const bin of Object.values(item.binary || {})) {
    const name = (bin.fileName || '').normalize('NFC');
    if (!/\.xlsx?$/i.test(name)) continue;
    const day = nameDate(name) || mailDay;
    if (day !== today) continue; // ไฟล์ของวันอื่น
    const kind = kinds.find(k => k.re.test(name));
    if (!kind) { others.add(name); continue; }
    const key = name + '|' + (bin.fileSize || '');
    if (!files[key]) files[key] = { kind: kind.name, name, key, bin }; // ไฟล์เดียวกันแนบมาหลายอีเมล = นับครั้งเดียว
  }
}
sd.others = [...others];

return Object.values(files)
  .filter(f => !sd.sent[f.key]) // อัปโหลดไปแล้ววันนี้
  .map(f => ({
    json: { kind: f.kind, fileName: f.name, key: f.key, folderId: sd.folderId || '' },
    binary: { data: f.bin },
  }));

// จำ ID โฟลเดอร์ของวันนี้ แล้วส่งไฟล์ทั้งหมดต่อไปอัปโหลด
const sd = $getWorkflowStaticData('global');
const folderId = $input.first().json.id;
sd.folderId = folderId;
return $('คัดไฟล์ Playlist').all().map(i => ({
  json: { ...i.json, folderId },
  binary: i.binary,
}));

// บันทึกว่าอัปโหลดไฟล์ไหนแล้ว และเขียนอีเมลสรุปว่าวันนี้ได้ครบ 11 แบบหรือยัง
const cfg = $('ตั้งค่า').first().json;
const sd = $getWorkflowStaticData('global');
const picked = $('คัดไฟล์ Playlist').all();
for (const p of picked) sd.sent[p.json.key] = p.json.kind;

const all = cfg.kinds.map(k => k.name);
const counts = {};
for (const k of Object.values(sd.sent)) counts[k] = (counts[k] || 0) + 1;
const haveN = all.filter(k => counts[k]).length;
const missing = all.filter(k => !counts[k]);
const multi = all.filter(k => counts[k] > 1);
const day = $now.setZone('Asia/Bangkok').setLocale('th').toFormat('d LLL yyyy');
const link = 'https://drive.google.com/drive/folders/' + sd.folderId;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');

const status = missing.length
  ? `<p>ยังขาด <b>${missing.length}</b> แบบ: ${missing.map(esc).join(', ')}</p><p>ระบบจะเช็กอีเมลทุกชั่วโมงจนถึง 18:00</p>`
  : `<p><b>ครบ 11 แบบแล้ว</b> ดาวน์โหลดทั้งโฟลเดอร์ แล้วลากลงระบบเติมใบเช็ครูปได้เลย</p>`;

const html = `<div style="font-family:Tahoma,sans-serif;font-size:15px;line-height:1.6">
<p>Playlist วันที่ ${esc(day)} — ได้แล้ว <b>${haveN}/${all.length}</b> แบบ</p>
<p>ไฟล์ที่เพิ่งเข้าโฟลเดอร์รอบนี้:</p>
<ul>${picked.map(p => `<li>${esc(p.json.kind)}: ${esc(p.json.fileName)}</li>`).join('')}</ul>
${status}
${multi.length ? `<p style="color:#b35a14"><b>บางแบบมีมากกว่า 1 ไฟล์:</b> ${multi.map(k => `${esc(k)} (${counts[k]} ไฟล์)`).join(', ')} — ตรวจว่าต้องใช้ฉบับไหน หรือใช้ทั้งหมด ก่อนลากลงระบบ</p>` : ''}
${(sd.others || []).length ? `<p style="color:#586274">ไฟล์ Excel อื่นของวันนี้ (ไม่ได้เก็บ เพราะชื่อไม่ตรง 11 แบบ):</p><ul style="color:#586274">${sd.others.map(n => `<li>${esc(n)}</li>`).join('')}</ul>` : ''}
<p><a href="${link}">เปิดโฟลเดอร์ Google Drive ของวันนี้</a></p>
</div>`;

return [{
  json: {
    to: cfg.notifyEmail,
    subject: `Playlist ${day}: ${haveN}/${all.length} แบบ` + (missing.length ? ' (ยังไม่ครบ)' : ' — ครบแล้ว'),
    html,
  },
}];
